+          onClick={() => runtime.actions?.collapse(nodeId, !frame.collapsed)}>{frame.collapsed ? 'Expand' : 'Collapse'}</button>
+        <button type="button" disabled={interaction.disabled} onClick={() => runtime.actions?.move(frame.boxId)}>Move</button>
